def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    overall_bg = counts.most_common(1)[0][0]

    # Locate the solid separator, distinguishing it from the dominant background.
    dividers = []
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != overall_bg:
            dividers.append(("h", r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != overall_bg:
            dividers.append(("v", c))

    orientation, k = dividers[0]

    def panel_bg(panel):
        return Counter(x for row in panel for x in row).most_common(1)[0][0]

    def foreground(panel, bg):
        vals = Counter(x for row in panel for x in row if x != bg)
        return vals.most_common(1)[0][0] if vals else bg

    if orientation == "v":
        n = min(k, w - k - 1)
        left = [row[:n] for row in grid]
        right = [row[k + 1:k + 1 + n] for row in grid]
        lbg, rbg = panel_bg(left), panel_bg(right)
        fill = foreground(right, rbg)
        out = [[fill] * n for _ in range(h)]
        for r in range(h):
            for c in range(n):
                if left[r][c] != lbg and right[r][c] != rbg:
                    out[r][c] = 3
        return out

    n = min(k, h - k - 1)
    top = grid[:n]
    bottom = grid[k + 1:k + 1 + n]
    tbg, bbg = panel_bg(top), panel_bg(bottom)
    fill = foreground(top, tbg)
    out = [[fill] * w for _ in range(n)]
    for r in range(n):
        for c in range(w):
            if top[r][c] != tbg and bottom[r][c] == bbg:
                out[r][c] = 3
    return out
